func TestFailedStateWriteDoesNotAdvanceReportTime(t *testing.T) {
 dir := t.TempDir()
 server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(http.StatusOK) }))
 defer server.Close()
 old := endpoint
 endpoint = server.URL
 defer func() { endpoint = old }()
 cfg := config.Default()
 cfg.Meta.StateDirectory = dir
 reporter, err := NewReporter(cfg, logrus.New())
 if err "'!= nil { t.Fatal(err) }
 previous := reporter.state.LastTimestamp
 if err := os.RemoveAll(dir); err != nil { t.Fatal(err) }
 if err := reporter.Report(context.Background()); err == nil { t.Fatal("expected state write error") }
 if reporter.state.LastTimestamp != previous { t.Fatalf("last report time advanced from %s to %s", previous, reporter.state.LastTimestamp) }
}
EOF
gofmt -w telemetry/telemetry_test.go config/config_test.go telemetry/telemetry.go
GOPROXY=off go test ./telemetry -run TestFailedStateWriteDoesNotAdvanceReportTime -count=1'

